INSERT INTO geez_questions (number, name, tag, art, question, choices, answers, explanation, seconds) VALUES
  (1, '광합성', '과학', 0, '식물이 광합성을 할 때 공기에서 흡수하는 기체는 무엇일까요?', '["산소","이산화탄소","질소","수소"]', '["이산화탄소"]', '식물은 빛에너지를 이용해 이산화탄소와 물로 양분을 만들어요.', 0),
  (2, '대양 탐사', '지리', 1, '세계에서 면적이 가장 넓은 바다는 어디일까요?', '["대서양","인도양","태평양","북극해"]', '["태평양"]', '태평양은 아시아·오세아니아와 아메리카 대륙 사이에 있어요.', 0),
  (3, '윤년 달력', '생활', 2, '윤년의 2월은 며칠까지 있을까요?', '[]', '["29","29일"]', '윤년에는 2월에 하루가 추가돼요.', 0),
  (4, '소리 전달', '과학', 3, '소리를 전달할 수 없는 환경은 어디일까요?', '["물속","진공","공기 중","철판 속"]', '["진공"]', '소리는 매질의 진동으로 전달돼요.', 0),
  (5, '훈민정음', '역사', 4, '조선에서 훈민정음을 창제한 왕은 누구일까요?', '[]', '["세종","세종대왕"]', '세종은 1443년에 훈민정음을 창제하고 1446년에 반포했어요.', 0),
  (6, '현악 합주', '문화', 5, '서양 관현악에서 바이올린보다 크고 첼로보다 작은 찰현악기는?', '["플루트","오보에","튜바","비올라"]', '["비올라"]', '비올라는 바이올린보다 낮은 음역을 담당해요.', 0),
  (7, '반감기', '과학', 6, '어느 방사성 물질의 양이 처음의 1/8로 줄었다면 반감기가 몇 번 지났을까요?', '[]', '["3","3번","3회"]', '반감기 세 번이면 남은 양은 1/2 × 1/2 × 1/2이에요.', 60),
  (8, '경도 원점', '지리', 7, '본초 자오선의 역사적 기준이 된 영국의 지역은 어디일까요?', '["옥스퍼드","도버","그리니치","케임브리지"]', '["그리니치"]', '그리니치 천문대를 통과하는 자오선이 경도 0도의 기준으로 채택됐어요.', 60),
  (9, '동의보감', '역사', 8, '조선 시대에 편찬된 의학서 『동의보감』의 대표 편찬자는?', '[]', '["허준"]', '허준은 여러 의학 자료를 집대성해 동의보감을 완성했어요.', 60),
  (10, '지구 궤도', '과학', 0, '지구의 자연 위성은 무엇일까요?', '[]', '["달","moon"]', '달은 지구 주위를 공전해요.', 0),
  (11, '행성 크기', '과학', 1, '태양계에서 가장 큰 행성은?', '["지구","토성","목성","금성"]', '["목성"]', '목성은 태양계 행성 중 지름과 질량이 가장 커요.', 0),
  (12, '제주 산길', '지리', 2, '대한민국 제주도에 있는 가장 높은 산은?', '[]', '["한라산"]', '한라산 정상에는 백록담이 있어요.', 0),
  (13, '하루 시계', '생활', 0, '하루는 몇 분일까요?', '[]', '["1440","1440분"]', '24시간에 60분을 곱하면 1440분이에요.', 0),
  (14, '피아노 음계', '문화', 1, '피아노 건반에서 도 다음으로 높은 온음계 음이름은?', '["미","파","레","솔"]', '["레"]', '도레미파솔라시도에서 도 다음은 레예요.', 0),
  (15, '분자식', '과학', 2, '물의 화학식은 무엇일까요?', '[]', '["H2O","H₂O"]', '물 분자 하나는 수소 원자 두 개와 산소 원자 한 개로 이뤄져요.', 0),
  (16, '이탈리아 수도', '지리', 0, '이탈리아 수도는 어느 도시일까요?', '["베네치아","로마","밀라노","나폴리"]', '["로마"]', '로마는 이탈리아의 수도예요.', 0),
  (17, '한산도 해전', '역사', 1, '임진왜란 때 한산도 대첩을 이끈 조선 수군 장수는?', '[]', '["이순신"]', '이순신은 한산도 앞바다에서 학익진을 펼쳤어요.', 0),
  (18, '거리 환산', '생활', 2, '길이 1킬로미터는 몇 미터일까요?', '[]', '["1000","1000m","1000미터"]', '킬로는 기본 단위의 천 배를 뜻해요.', 0),
  (19, '바다 포유류', '과학', 0, '다음 중 포유류는 무엇일까요?', '["상어","돌고래","참치","해마"]', '["돌고래"]', '돌고래는 폐로 숨을 쉬고 새끼에게 젖을 먹여요.', 0),
  (20, '전통 춤판', '문화', 1, '탈춤 공연에서 얼굴에 쓰는 물건은 무엇일까요?', '[]', '["탈","가면"]', '탈을 쓰고 춤과 익살스러운 연기를 펼쳐요.', 0);
INSERT INTO geez_questions (number, name, tag, art, question, choices, answers, explanation, seconds) VALUES
  (21, '일본 수도', '지리', 2, '일본의 수도는 어디일까요?', '[]', '["도쿄","동경"]', '도쿄는 일본 혼슈에 있어요.', 0),
  (22, '연필 광물', '생활', 0, '연필심의 주재료인 검은 광물은?', '["납","흑연","석영","석회석"]', '["흑연"]', '연필심은 흑연에 점토 등을 섞어 만들어요.', 0),
  (23, '기체 교환', '과학', 1, '사람의 호흡에서 공기와 혈액 사이의 기체 교환이 일어나는 기관은?', '[]', '["폐","허파"]', '폐 속의 작은 폐포에서 산소와 이산화탄소를 교환해요.', 0),
  (24, '축구 선발대', '문화', 2, '축구에서 골키퍼를 포함해 한 팀이 정상적으로 경기를 시작하는 인원은?', '[]', '["11","11명","열한 명"]', '축구는 팀당 열한 명이 선발로 출전해요.', 0),
  (25, '위도 경계', '지리', 0, '지구를 북반구와 남반구로 나누는 위도 0도의 선은?', '[]', '["적도"]', '적도는 두 극에서 같은 거리에 있는 가상의 선이에요.', 0),
  (26, '곤충 다리', '과학', 1, '곤충의 다리는 보통 몇 개일까요?', '[]', '["6","6개","여섯 개"]', '곤충은 가슴에 세 쌍의 다리가 있어요.', 0),
  (27, '부피 환산', '생활', 2, '1리터는 몇 밀리리터일까요?', '[]', '["1000","1000ml","1000밀리리터"]', '밀리리터는 리터의 천분의 일이에요.', 0),
  (28, '활 켜는 악단', '문화', 0, '현이 네 개이고 턱에 받쳐 활로 켜는, 비올라보다 작은 악기는?', '["첼로","바이올린","해금","하프"]', '["바이올린"]', '바이올린은 네 현을 활로 켜며 연주해요.', 0),
  (29, '기자 유적', '지리', 1, '피라미드와 스핑크스가 있는 기자는 어느 나라의 도시일까요?', '[]', '["이집트"]', '기자는 이집트 수도 카이로 인근에 있어요.', 0),
  (30, '물의 상태', '과학', 2, '액체 상태의 물이 고체로 바뀌는 현상은?', '["증발","응결","승화","응고"]', '["응고"]', '물이 얼음이 되는 과정이 응고예요.', 0),
  (31, '만리장성', '역사', 0, '거대한 성곽인 만리장성이 있는 나라는?', '[]', '["중국"]', '만리장성은 중국 북부 여러 지역에 걸쳐 있어요.', 0),
  (32, '판소리 장단', '문화', 1, '판소리에서 소리꾼 옆에서 북을 치는 사람은?', '["지휘자","악장","고수","해설자"]', '["고수"]', '고수는 북장단과 추임새로 소리를 받쳐 줘요.', 0),
  (33, '삼각형 내각', '생활', 2, '삼각형의 내각을 모두 더하면 몇 도일까요? 평면을 기준으로 해요.', '[]', '["180","180도"]', '평면 삼각형의 내각의 합은 180도예요.', 0),
  (34, '달의 모양', '과학', 0, '음력 보름 무렵 둥글게 보이는 달은?', '[]', '["보름달","만월"]', '지구에서 볼 때 달의 밝은 면이 거의 전부 보이는 시기예요.', 0),
  (35, '에펠탑', '지리', 1, '에펠탑이 있는 프랑스의 도시는 어디일까요?', '[]', '["파리"]', '에펠탑은 파리 센강 근처에 있어요.', 0),
  (36, '영문 나침반', '생활', 2, '영어 나침반에서 서쪽을 가리키는 글자는?', '["N","E","S","W"]', '["W"]', 'West의 첫 글자 W가 서쪽이에요.', 0),
  (37, '대기 성분', '과학', 3, '지구 대기에서 부피 비율이 가장 높은 기체는?', '["산소","질소","아르곤","이산화탄소"]', '["질소"]', '건조한 공기의 약 78%는 질소예요.', 0),
  (38, '호주 수도', '지리', 4, '호주의 수도는 어디일까요?', '["시드니","멜버른","캔버라","브리즈번"]', '["캔버라"]', '호주의 연방 수도는 내륙 도시 캔버라예요.', 0),
  (39, '서라벌', '역사', 5, '신라의 옛 도읍인 서라벌은 오늘날 어느 도시일까요?', '[]', '["경주","경주시"]', '경주에는 첨성대와 여러 신라 왕릉이 남아 있어요.', 0),
  (40, '어린 왕자', '문화', 3, '『어린 왕자』를 쓴 프랑스 작가는?', '[]', '["생텍쥐페리","앙투안 드 생텍쥐페리"]', '앙투안 드 생텍쥐페리는 비행사이자 작가였어요.', 0);
INSERT INTO geez_questions (number, name, tag, art, question, choices, answers, explanation, seconds) VALUES
  (41, '할인 계산', '생활', 4, '판매 가격이 2만 원인 상품을 15% 할인하면 얼마일까요? 원 단위로 답하세요.', '[]', '["17000","17000원"]', '2만 원의 15%인 3천 원을 빼면 1만 7천 원이에요.', 0),
  (42, '운동 법칙', '과학', 5, '물체가 운동 상태를 유지하려는 성질은?', '["부력","마찰력","탄성","관성"]', '["관성"]', '외력이 작용하지 않으면 물체는 기존의 정지 또는 등속 직선 운동 상태를 유지해요.', 0),
  (43, '남미 산맥', '지리', 3, '남아메리카 서부를 따라 길게 뻗은 산맥은?', '[]', '["안데스","안데스산맥","안데스 산맥"]', '안데스산맥은 남아메리카의 태평양 쪽 가장자리를 따라 이어져요.', 0),
  (44, '고려 건국', '역사', 4, '고려를 건국한 인물의 이름은?', '[]', '["왕건","태조 왕건"]', '왕건은 918년에 고려를 세웠어요.', 0),
  (45, '모나리자', '문화', 5, '『모나리자』를 그린 화가는?', '["미켈란젤로","클로드 모네","빈센트 반 고흐","레오나르도 다 빈치"]', '["레오나르도 다 빈치"]', '레오나르도 다 빈치는 르네상스 시대 이탈리아의 화가예요.', 0),
  (46, '웹 통신', '생활', 3, '인터넷 주소에서 HTTPS의 마지막 S가 뜻하는 영어 단어는?', '[]', '["secure"]', 'HTTPS는 보안이 적용된 HTTP를 뜻해요.', 0),
  (47, '원소 기호', '과학', 4, '원소 기호 Fe가 가리키는 금속은?', '[]', '["철"]', 'Fe는 철의 라틴어 이름 ferrum에서 왔어요.', 0),
  (48, '북아프리카 사막', '지리', 5, '아프리카 북부에 넓게 펼쳐진 사막은?', '[]', '["사하라","사하라 사막","사하라사막"]', '사하라는 북아프리카 여러 나라에 걸쳐 있어요.', 0),
  (49, '백제 사비성', '역사', 3, '백제의 마지막 수도 사비는 오늘날 주로 어느 지역에 해당할까요?', '["경주","부여","평양","개성"]', '["부여"]', '오늘날 충남 부여에 백제 사비 도성 유적이 남아 있어요.', 0),
  (50, '악보의 가로줄', '문화', 4, '오선보의 평행한 가로줄은 몇 개일까요?', '[]', '["5","5개","다섯 개"]', '다섯 줄과 그 사이의 네 칸으로 음높이를 표시해요.', 0),
  (51, '카드 무늬', '생활', 5, '표준 52장 카드 한 벌에서 조커를 빼면 무늬는 몇 종류일까요?', '[]', '["4","4개","4종류"]', '스페이드·하트·다이아몬드·클럽 네 종류예요.', 0),
  (52, '별의 움직임', '과학', 3, '지구 자전 때문에 별은 밤하늘에서 대체로 어느 방향으로 이동해 보일까요?', '["서쪽에서 동쪽","동쪽에서 서쪽","남쪽에서 북쪽","북쪽에서 남쪽"]', '["동쪽에서 서쪽"]', '지구가 서쪽에서 동쪽으로 자전해 하늘은 반대 방향으로 도는 듯 보여요.', 0),
  (53, '독일 수도', '지리', 4, '독일의 수도는 어디일까요?', '[]', '["베를린"]', '베를린은 독일 북동부에 있어요.', 0),
  (54, '팔만대장경', '역사', 5, '팔만대장경 경판을 보관한 사찰은?', '["불국사","통도사","법주사","해인사"]', '["해인사"]', '합천 해인사의 장경판전에 경판을 보관해요.', 0),
  (55, '비극의 극작가', '문화', 3, '『로미오와 줄리엣』을 쓴 극작가는?', '[]', '["셰익스피어","윌리엄 셰익스피어","윌리엄 셰익스피어"]', '윌리엄 셰익스피어는 영국의 극작가예요.', 0),
  (56, '빛의 삼원색', '생활', 4, '빛의 삼원색 RGB에서 G가 뜻하는 색은?', '[]', '["초록","녹색","초록색","green"]', 'RGB는 빨강·초록·파랑 빛을 뜻해요.', 0),
  (57, '지진의 좌표', '과학', 5, '지진이 시작된 지하 지점 바로 위의 지표 지점은?', '["진원","진도","단층","진앙"]', '["진앙"]', '진원은 지진이 시작된 지하 지점이고 진앙은 그 바로 위 지표예요.', 0),
  (58, '두 대륙 사이의 바다', '지리', 3, '유럽과 아프리카 사이에서 대서양과 이어지는 바다는?', '[]', '["지중해"]', '지중해는 지브롤터 해협을 통해 대서양과 이어져요.', 0),
  (59, '고려청자', '역사', 4, '고려청자의 대표적인 푸른빛을 흔히 어떤 색이라고 부를까요?', '["주홍색","감청색","비색","황토색"]', '["비색"]', '고려청자의 은은한 청록빛을 비색이라고 불러요.', 0),
  (60, '야구 마운드', '문화', 5, '야구에서 한 투수가 한 경기의 처음부터 끝까지 던지는 것은?', '[]', '["완투"]', '완투하면서 실점도 하지 않으면 완봉이라고 해요.', 0);
INSERT INTO geez_questions (number, name, tag, art, question, choices, answers, explanation, seconds) VALUES
  (61, '이진법', '생활', 3, '컴퓨터의 이진법에서 사용하는 숫자 두 개는?', '["1과 2","0과 1","0과 9","2와 8"]', '["0과 1"]', '이진법은 각 자리를 0 또는 1로 표시해요.', 0),
