  (64, '독립 만세', '역사', 3, '독립선언서를 낭독하고 만세 시위를 벌인 1919년의 운동은?', '[]', '["3·1 운동","3.1운동","삼일운동","3·1운동","3.1 운동"]', '1919년 3월 1일을 계기로 독립 만세 운동이 전국으로 퍼졌어요.', 0),
  (65, '악보의 셈여림', '문화', 4, '서양 음악에서 점점 세게 연주하라는 말은?', '["데크레셴도","피아니시모","크레셴도","스타카토"]', '["크레셴도"]', '크레셴도는 음량을 점점 키우라는 표시예요.', 0),
  (66, '데이터 단위', '생활', 5, '1바이트는 몇 비트일까요? 현대 컴퓨터를 기준으로 해요.', '[]', '["8","8비트","8bit"]', '현대 컴퓨터에서는 여덟 비트를 한 바이트로 다뤄요.', 0),
  (67, '숨바꼭질 생물', '과학', 3, '어떤 생물이 주변 환경과 비슷한 색이나 무늬로 몸을 숨기는 현상은?', '["발아","위장","탈피","변태"]', '["위장"]', '주변과 구별하기 어려워지도록 하는 것이 위장이에요.', 0),
  (68, '한반도 해협', '지리', 4, '한반도와 일본 규슈 사이의 해협은?', '[]', '["대한 해협","대한해협"]', '대한 해협은 동해와 동중국해를 연결해요.', 0),
  (69, '한양 궁궐', '역사', 5, '조선의 수도 한양에 지어진 첫 번째 정궁은?', '[]', '["경복궁"]', '경복궁은 조선 태조 때 건립됐어요.', 0),
  (70, '한글 모음', '문화', 3, '한글 자모 가운데 기본 모음은 몇 개일까요? 현대 한글 기준이에요.', '[]', '["10","10개","열 개"]', '기본 모음 열 개와 복합 모음 열한 개로 현대 한글 모음 21자를 구성해요.', 0),
  (71, '화씨 온도계', '생활', 4, '온도계의 화씨 눈금에서 물의 어는점은 표준 기압에서 몇 도일까요?', '[]', '["32","32도","32°F"]', '섭씨 0도는 화씨 32도예요.', 0),
  (72, '원자핵', '과학', 6, '원소의 원자번호는 원자핵 속 어떤 입자의 수와 같을까요?', '["중성자","광자","중성미자","양성자"]', '["양성자"]', '양성자의 개수가 원소의 종류를 결정해요.', 60),
  (73, '이스탄불 해협', '지리', 7, '유럽과 아시아에 걸친 이스탄불을 가로지르는 해협은?', '["베링 해협","보스포루스 해협","도버 해협","마젤란 해협"]', '["보스포루스 해협"]', '보스포루스 해협은 흑해와 마르마라해를 연결해요.', 60),
  (74, '고려 금속활자', '역사', 8, '고려 말 금속활자로 인쇄한 책으로 흥덕사에서 간행된 것은?', '[]', '["직지","직지심체요절"]', '1377년에 청주 흥덕사에서 금속활자로 인쇄했어요.', 60),
  (75, '사계 협주곡', '문화', 6, '『사계』라는 네 편의 바이올린 협주곡을 작곡한 사람은?', '[]', '["비발디","안토니오 비발디"]', '비발디는 봄·여름·가을·겨울을 각각 협주곡으로 표현했어요.', 60),
  (76, '수요와 공급', '생활', 7, '수요가 일정할 때 공급이 줄어들면 일반적인 수요·공급 모형에서 균형가격은?', '["하락한다","상승한다","항상 0이 된다","반드시 고정된다"]', '["상승한다"]', '공급곡선이 왼쪽으로 이동하면 균형가격은 올라가요.', 60),
  (77, '빛의 경로', '과학', 8, '빛이 한 매질에서 다른 매질로 들어갈 때 진행 방향이 꺾이는 현상은?', '[]', '["굴절"]', '매질에 따라 빛의 속도가 달라져 진행 방향이 바뀔 수 있어요.', 60),
  (78, '남반구 수도', '지리', 6, '다음 중 남반구에 있는 수도는?', '["오슬로","리스본","오타와","웰링턴"]', '["웰링턴"]', '뉴질랜드의 수도 웰링턴은 남반구에 있어요.', 60),
  (79, '정약용의 서재', '역사', 7, '조선 후기 정약용이 지방 관리의 자세와 실무를 정리한 책은?', '[]', '["목민심서"]', '목민심서는 수령이 백성을 다스릴 때의 원칙과 실무를 다뤄요.', 60),
  (80, '무대의 속삭임', '문화', 8, '연극에서 등장인물이 관객에게만 들리는 것으로 약속하고 하는 말은?', '["합창","지문","방백","낭독"]', '["방백"]', '방백은 무대의 다른 등장인물에게는 들리지 않는 것으로 처리해요.', 60);
INSERT INTO geez_questions (number, name, tag, art, question, choices, answers, explanation, seconds) VALUES
  (81, '동전 확률', '생활', 6, '공정한 동전을 독립적으로 세 번 던져 세 번 모두 앞면일 확률은? 기약분수로 입력하세요.', '[]', '["1/8","8분의 1","8분의1"]', '각 시행의 확률 1/2을 세 번 곱해요.', 60),
  (82, '겨울 결정', '과학', 7, '수증기가 액체를 거치지 않고 얼음 결정이 되는 예는?', '["이슬 형성","서리 형성","물이 끓음","얼음이 녹음"]', '["서리 형성"]', '서리는 수증기가 차가운 표면에서 바로 고체가 되어 생길 수 있어요.', 60),
  (83, '두 바다의 물길', '지리', 8, '지중해와 홍해를 이어 주는 인공 수로는?', '[]', '["수에즈 운하","수에즈운하"]', '이집트의 수에즈 운하는 아프리카 대륙을 돌아가지 않는 항로를 제공해요.', 60),
  (84, '조선의 사관', '역사', 6, '조선의 왕별 역사를 날짜 순서로 기록한 편년체 역사서는?', '[]', '["조선왕조실록","조선 왕조 실록"]', '조선왕조실록은 왕이 세상을 떠난 뒤 관련 기록을 모아 편찬했어요.', 60),
  (85, '별밤의 화가', '문화', 7, '『별이 빛나는 밤』을 그린 네덜란드 출신 화가는?', '["살바도르 달리","빈센트 반 고흐","폴 세잔","피에르 오귀스트 르누아르"]', '["빈센트 반 고흐"]', '반 고흐는 소용돌이치는 붓질로 밤하늘을 표현했어요.', 60),
  (86, '복리 저금통', '생활', 8, '원금 10만 원을 연 10% 복리로 2년간 두면 이자는 총 얼마일까요? 세금은 제외해요.', '[]', '["21000","21000원"]', '1년 후 11만 원, 2년 후 12만 1천 원이 되어 이자는 2만 1천 원이에요.', 60),
  (87, '지각판 경계', '과학', 6, '판 구조론에서 두 판이 서로 멀어지는 경계는?', '["수렴형 경계","보존형 경계","충돌 경계","발산형 경계"]', '["발산형 경계"]', '발산형 경계에서는 판이 벌어지며 새로운 지각이 만들어질 수 있어요.', 60),
  (88, '남미의 뱃길', '지리', 7, '남아메리카 최남단 부근에서 본토와 티에라델푸에고섬을 가르는 해협은?', '["호르무즈 해협","마젤란 해협","말라카 해협","베링 해협"]', '["마젤란 해협"]', '마젤란 해협은 남아메리카 남단의 대서양과 태평양을 이어 줘요.', 60),
  (89, '왕건의 당부', '역사', 8, '고려에서 후대 왕들에게 남긴 태조 왕건의 열 가지 당부를 무엇이라고 할까요?', '[]', '["훈요십조","훈요 10조","훈요 10 조"]', '훈요십조에는 불교와 정치 운영 등에 관한 당부가 담겼어요.', 60),
  (90, '반음 계단', '문화', 6, '한 음을 반음 올리라는 음악 기호의 이름은?', '[]', '["올림표","샤프","sharp"]', '올림표는 ♯ 모양이며 해당 음을 반음 높여요.', 60),
  (91, '가격 변동', '생활', 7, '어떤 상품 가격이 20% 오른 뒤 다시 20% 내렸다면 처음 가격의 몇 %일까요?', '[]', '["96","96%"]', '처음 가격에 1.2와 0.8을 곱하면 0.96이 돼요.', 60),
  (92, '소리 높낮이', '과학', 8, '소리의 높낮이를 주로 결정하는 물리량은?', '["진폭","음속","진동수","매질의 질량"]', '["진동수"]', '진동수가 높을수록 높은 음으로 들려요.', 60),
  (93, '위도의 끝', '지리', 6, '지구에서 위도 90도인 지점은 모두 몇 곳일까요? 북위와 남위를 모두 포함해요.', '[]', '["2","2곳","두 곳"]', '북극점과 남극점 두 곳이에요.', 60),
  (94, '조선 천문대', '역사', 7, '조선 시대 천문 관측 기구로 해와 달·별의 위치를 측정하는 데 쓴 것은?', '["자격루","혼천의","측우기","거중기"]', '["혼천의"]', '혼천의는 여러 개의 둥근 고리를 이용한 천문 관측 기구예요.', 60),
  (95, '소설 속 화자', '문화', 8, '소설에서 작품 속 인물인 ‘나’가 다른 주요 인물의 이야기를 관찰해 전하는 시점은?', '[]', '["1인칭 관찰자 시점","일인칭 관찰자 시점"]', '화자가 작품 속에 등장하면서 다른 인물의 행동을 중심으로 서술해요.', 60),
  (96, '상품권 할인율', '생활', 6, '액면가 1만 원인 상품권을 9천 원에 샀다면 액면가 기준 할인율은?', '[]', '["10%","10","10퍼센트"]', '할인액 1천 원을 액면가 1만 원으로 나누면 10%예요.', 60),
  (97, '운동 에너지', '과학', 7, '질량이 일정한 물체의 속력이 두 배가 되면 운동 에너지는 몇 배일까요?', '[]', '["4","4배","네 배"]', '운동 에너지는 속력의 제곱에 비례해요.', 60),
  (98, '경도와 시차', '지리', 8, '경도 15도 차이가 평균 태양시로 약 몇 시간의 차이에 해당할까요?', '[]', '["1","1시간","한 시간"]', '지구가 약 24시간에 360도 회전하므로 한 시간에 약 15도예요.', 60),
  (99, '김정호의 지도', '역사', 6, '조선 후기 김정호가 목판으로 제작한 전국 지도는?', '[]', '["대동여지도"]', '대동여지도는 여러 장을 이어 전국을 볼 수 있도록 제작됐어요.', 60),
  (100, '책의 끝장', '문화', 7, '책이나 글의 끝에 덧붙여 쓰는 글을 가리키는 말은?', '["서문","발문","표제","목차"]', '["발문"]', '발문은 책을 쓴 경위나 감상 등을 끝부분에 덧붙인 글이에요.', 60);
