  (115, '측정 단위 · 힘', '과학', 6, '힘의 SI 단위 이름은?', '["파스칼","뉴턴","몰","헤르츠"]', '["뉴턴"]', '1 N은 1 kg의 물체에 1 m/s²의 가속도를 주는 힘이에요.', 60),
  (116, '측정 단위 · 압력', '과학', 3, '압력의 SI 단위 이름은?', '[]', '["파스칼"]', '1 Pa은 1 m²에 1 N의 힘이 수직으로 작용하는 압력이에요.', 0),
