  (136, '상태 변화 · 액체가 된 기체', '과학', 4, '수증기처럼 기체가 액체로 바뀌는 변화를 무엇이라고 할까요?', '[]', '["액화"]', '기체가 에너지를 잃어 액체 상태가 돼요.', 0),
  (137, '상태 변화 · 사라지는 드라이아이스', '과학', 2, '드라이아이스처럼 고체가 직접 기체로 바뀌는 변화를 무엇이라고 할까요?', '[]', '["승화"]', '액체 상태를 거치지 않아요.', 0),
