  (290, '우리 문화유산 · 방화수류정의 성곽', '역사', 3, '어느 문화유산을 설명한 것일까요? 정조가 건설한 성곽으로 방화수류정과 화홍문이 있는 곳', '[]', '["수원 화성","화성"]', '수원 화성 — 정조가 건설한 성곽으로 방화수류정과 화홍문이 있는 곳.', 0),
  (291, '우리 문화유산 · 의례의 그림 기록', '역사', 7, '어느 문화유산을 설명한 것일까요? 조선 왕실의 의례 과정을 글과 그림으로 정리한 기록물', '["에밀레종","석굴암","백제 금동대향로","의궤"]', '["의궤"]', '의궤 — 조선 왕실의 의례 과정을 글과 그림으로 정리한 기록물.', 60),
  (292, '우리 문화유산 · 경주의 큰 종', '역사', 4, '어느 문화유산을 설명한 것일까요? 공식 명칭이 성덕대왕신종인 경주의 큰 종의 널리 알려진 별명', '[]', '["에밀레종"]', '에밀레종 — 공식 명칭이 성덕대왕신종인 경주의 큰 종의 널리 알려진 별명.', 0),
  (293, '옛 사회 제도 · 시험으로 뽑은 관리', '역사', 0, '다음 설명에 해당하는 제도나 기관은? 고려와 조선에서 시험을 통해 관리를 선발하던', '[]', '["과거제","과거"]', '과거제 — 고려와 조선에서 시험을 통해 관리를 선발하던.', 0),
  (294, '옛 사회 제도 · 지방의 관립 학교', '역사', 5, '다음 설명에 해당하는 제도나 기관은? 조선에서 각 지방에 설치해 교육과 제사를 담당한 관립 교육 기관', '[]', '["향교"]', '향교 — 조선에서 각 지방에 설치해 교육과 제사를 담당한 관립 교육 기관.', 0),
  (295, '옛 사회 제도 · 유학자의 사립 학교', '역사', 1, '다음 설명에 해당하는 제도나 기관은? 조선에서 유학자 제향과 교육을 담당한 사립 교육 기관', '[]', '["서원"]', '서원 — 조선에서 유학자 제향과 교육을 담당한 사립 교육 기관.', 0),
  (296, '옛 사회 제도 · 왕명의 출납', '역사', 3, '다음 설명에 해당하는 제도나 기관은? 조선에서 왕명의 출납을 맡아 오늘날 비서실에 비유되는 관청', '[]', '["승정원"]', '승정원 — 조선에서 왕명의 출납을 맡아 오늘날 비서실에 비유되는 관청.', 0),
  (297, '옛 사회 제도 · 왕에게 올리는 간언', '역사', 2, '다음 설명에 해당하는 제도나 기관은? 조선에서 관리의 비리를 감찰한 사헌부와 함께 언론을 담당하며 간쟁한 관청', '[]', '["사간원"]', '사간원 — 조선에서 관리의 비리를 감찰한 사헌부와 함께 언론을 담당하며 간쟁한 관청.', 0),
  (298, '옛 사회 제도 · 세 군대의 항쟁', '역사', 4, '다음 설명에 해당하는 제도나 기관은? 고려 무신 정권의 군사 조직으로 좌별초·우별초·신의군을 합친 것', '[]', '["삼별초"]', '삼별초 — 고려 무신 정권의 군사 조직으로 좌별초·우별초·신의군을 합친 것.', 0),
  (299, '옛 사회 제도 · 공물 대신 낸 쌀', '역사', 8, '다음 설명에 해당하는 제도나 기관은? 조선에서 공물을 쌀·포·동전 등으로 납부하게 한 납세 제도', '[]', '["대동법"]', '대동법 — 조선에서 공물을 쌀·포·동전 등으로 납부하게 한 납세 제도.', 60),
  (300, '옛 사회 제도 · 군포 한 필', '역사', 5, '다음 설명에 해당하는 제도나 기관은? 조선에서 농민이 내던 군포를 보통 2필에서 1필로 줄인 제도', '[]', '["균역법"]', '균역법 — 조선에서 농민이 내던 군포를 보통 2필에서 1필로 줄인 제도.', 0);
INSERT INTO geez_questions (number, name, tag, art, question, choices, answers, explanation, seconds) VALUES
  (301, '세계사 연도 · 바스티유의 날', '역사', 0, '다음 사건이 일어난 연도는? 바스티유 감옥 습격을 계기로 한 프랑스 혁명의 시작', '["1776","1789","1939","1989"]', '["1789"]', '1789 — 바스티유 감옥 습격을 계기로 한 프랑스 혁명의 시작.', 0),
  (302, '세계사 연도 · 미국의 독립 선언', '역사', 3, '다음 사건이 일어난 연도는? 미국 독립 선언의 채택', '[]', '["1776","1776년"]', '1776 — 미국 독립 선언의 채택.', 0),
  (303, '세계사 연도 · 제1차 세계대전의 시작', '역사', 1, '다음 사건이 일어난 연도는? 제1차 세계대전의 발발', '["1939","1989","1453","1914"]', '["1914"]', '1914 — 제1차 세계대전의 발발.', 0),
  (304, '세계사 연도 · 폴란드 침공', '역사', 4, '다음 사건이 일어난 연도는? 유럽에서 독일의 폴란드 침공으로 제2차 세계대전이 시작된 해', '[]', '["1939","1939년"]', '1939 — 유럽에서 독일의 폴란드 침공으로 제2차 세계대전이 시작된 해.', 0),
  (305, '세계사 연도 · 국제연합의 출범', '역사', 2, '다음 사건이 일어난 연도는? 국제연합 헌장이 발효된 해', '["1989","1453","1945","1776"]', '["1945"]', '1945 — 국제연합 헌장이 발효된 해.', 0),
  (306, '세계사 연도 · 베를린 장벽의 개방', '역사', 5, '다음 사건이 일어난 연도는? 베를린 장벽의 통행이 개방된 해', '[]', '["1989","1989년"]', '1989 — 베를린 장벽의 통행이 개방된 해.', 0),
  (307, '세계사 연도 · 아폴로 11호의 해', '역사', 6, '다음 사건이 일어난 연도는? 인류가 아폴로 11호로 처음 달에 착륙한 해', '["1453","1969","1776","1939"]', '["1969"]', '1969 — 인류가 아폴로 11호로 처음 달에 착륙한 해.', 60),
  (308, '세계사 연도 · 콘스탄티노폴리스 함락', '역사', 3, '다음 사건이 일어난 연도는? 동로마 제국 수도 콘스탄티노폴리스가 오스만 제국에 함락된 해', '[]', '["1453","1453년"]', '1453 — 동로마 제국 수도 콘스탄티노폴리스가 오스만 제국에 함락된 해.', 0),
  (309, '고대 문명 · 나일 강의 군주', '역사', 0, '다음 설명에 해당하는 고대 세계의 명칭은? 고대 이집트 왕을 가리키는 칭호', '["쐐기 문자","아스테카","지구라트","파라오"]', '["파라오"]', '파라오 — 고대 이집트 왕을 가리키는 칭호.', 0),
  (310, '고대 문명 · 점토판의 글자', '역사', 4, '다음 설명에 해당하는 고대 세계의 명칭은? 메소포타미아에서 점토판에 갈대 펜으로 새긴 쐐기 모양의 문자', '[]', '["쐐기 문자","설형 문자"]', '쐐기 문자 — 메소포타미아에서 점토판에 갈대 펜으로 새긴 쐐기 모양의 문자.', 0),
  (311, '고대 문명 · 안데스의 매듭', '역사', 1, '다음 설명에 해당하는 고대 세계의 명칭은? 서로 다른 길이의 줄과 매듭으로 기록을 남긴 안데스의 제국', '["아스테카","지구라트","잉카 제국","헬레니즘 문화"]', '["잉카 제국"]', '잉카 제국 — 서로 다른 길이의 줄과 매듭으로 기록을 남긴 안데스의 제국.', 0),
  (312, '고대 문명 · 호수 위의 수도', '역사', 5, '다음 설명에 해당하는 고대 세계의 명칭은? 테노치티틀란을 수도로 삼은 멕시코 고원의 문명', '[]', '["아스테카","아즈텍"]', '아스테카 — 테노치티틀란을 수도로 삼은 멕시코 고원의 문명.', 0),
  (313, '고대 문명 · 하라파의 문명', '역사', 2, '다음 설명에 해당하는 고대 세계의 명칭은? 모헨조다로와 하라파가 대표하는 고대 문명', '["지구라트","인더스 문명","헬레니즘 문화","쐐기 문자"]', '["인더스 문명"]', '인더스 문명 — 모헨조다로와 하라파가 대표하는 고대 문명.', 0),
  (314, '고대 문명 · 계단 위의 신전', '역사', 3, '다음 설명에 해당하는 고대 세계의 명칭은? 고대 메소포타미아에서 신전을 높이 쌓아 올린 계단식 건축물', '[]', '["지구라트"]', '지구라트 — 고대 메소포타미아에서 신전을 높이 쌓아 올린 계단식 건축물.', 0),
  (315, '고대 문명 · 로마의 경기장', '역사', 7, '다음 설명에 해당하는 고대 세계의 명칭은? 로마에서 검투 경기 등이 열린 거대한 원형 경기장', '["헬레니즘 문화","쐐기 문자","아스테카","콜로세움"]', '["콜로세움"]', '콜로세움 — 로마에서 검투 경기 등이 열린 거대한 원형 경기장.', 60),
  (316, '고대 문명 · 동서 문화의 융합', '역사', 4, '다음 설명에 해당하는 고대 세계의 명칭은? 알렉산드로스의 정복 이후 그리스 문화와 동방 문화가 융합된 문화', '[]', '["헬레니즘 문화","헬레니즘"]', '헬레니즘 문화 — 알렉산드로스의 정복 이후 그리스 문화와 동방 문화가 융합된 문화.', 0),
  (317, '인물과 업적 · 몽골의 초대 대칸', '역사', 0, '이 업적을 남긴 인물은 누구일까요? 몽골 제국을 세우고 초대 대칸이 된', '["진시황","조지 워싱턴","칭기즈 칸","마하트마 간디"]', '["칭기즈 칸"]', '칭기즈 칸와 관련된 역사적 업적이에요.', 0),
  (318, '인물과 업적 · 중국의 첫 황제', '역사', 5, '이 업적을 남긴 인물은 누구일까요? 고대 중국을 통일하고 처음으로 황제라는 칭호를 사용한', '[]', '["진시황"]', '진시황와 관련된 역사적 업적이에요.', 0),
  (319, '인물과 업적 · 알프스를 넘은 장군', '역사', 1, '이 업적을 남긴 인물은 누구일까요? 카르타고 장군으로 코끼리와 알프스산맥을 넘은', '["조지 워싱턴","한니발","마하트마 간디","마르틴 루터"]', '["한니발"]', '한니발와 관련된 역사적 업적이에요.', 0),
  (320, '인물과 업적 · 미국의 첫 대통령', '역사', 3, '이 업적을 남긴 인물은 누구일까요? 미국의 초대 대통령으로 취임한', '[]', '["조지 워싱턴","워싱턴"]', '조지 워싱턴와 관련된 역사적 업적이에요.', 0);
INSERT INTO geez_questions (number, name, tag, art, question, choices, answers, explanation, seconds) VALUES
  (321, '인물과 업적 · 노예 해방 선언', '역사', 2, '이 업적을 남긴 인물은 누구일까요? 미국 남북전쟁 때 노예 해방 선언을 발표한 대통령인', '["마하트마 간디","마르틴 루터","진시황","에이브러햄 링컨"]', '["에이브러햄 링컨"]', '에이브러햄 링컨와 관련된 역사적 업적이에요.', 0),
  (322, '인물과 업적 · 소금 행진', '역사', 4, '이 업적을 남긴 인물은 누구일까요? 인도 독립운동에서 비폭력 불복종과 소금 행진을 이끈', '[]', '["마하트마 간디","간디"]', '마하트마 간디와 관련된 역사적 업적이에요.', 0),
  (323, '인물과 업적 · 로마법의 집대성', '역사', 8, '이 업적을 남긴 인물은 누구일까요? 동로마 제국에서 『로마법 대전』 편찬을 명한 황제인', '["마르틴 루터","진시황","유스티니아누스 1세","조지 워싱턴"]', '["유스티니아누스 1세"]', '유스티니아누스 1세와 관련된 역사적 업적이에요.', 60),
  (324, '인물과 업적 · 95개조 반박문', '역사', 5, '이 업적을 남긴 인물은 누구일까요? 16세기 독일에서 95개조 반박문으로 종교 개혁에 영향을 준', '[]', '["마르틴 루터","루터"]', '마르틴 루터와 관련된 역사적 업적이에요.', 0),
  (325, '발명과 교류 · 덮개돌 무덤', '역사', 0, '다음 설명에 해당하는 이름은? 한반도의 청동기 시대를 대표하는 돌무덤으로 거대한 덮개돌을 얹은 것', '["비단길","고인돌","청해진","자격루"]', '["고인돌"]', '고인돌 — 한반도의 청동기 시대를 대표하는 돌무덤으로 거대한 덮개돌을 얹은 것.', 0),
  (326, '발명과 교류 · 비단의 무역로', '역사', 3, '다음 설명에 해당하는 이름은? 동서 교역로 가운데 중국 비단의 이름을 딴 길', '[]', '["비단길","실크로드"]', '비단길 — 동서 교역로 가운데 중국 비단의 이름을 딴 길.', 0),
