  (445, '파일과 편집 · 파일의 예비 사본', '생활', 0, '다음 작업의 이름은? 중요한 파일을 별도 저장 장치 등에 복사해 두는', '["압축","백업","스캔","자르기"]', '["백업"]', '백업 — 중요한 파일을 별도 저장 장치 등에 복사해 두는.', 0),
  (446, '파일과 편집 · 작게 묶은 파일', '생활', 3, '다음 작업의 이름은? 자료를 작은 크기로 묶거나 줄여 저장하는', '[]', '["압축"]', '압축 — 자료를 작은 크기로 묶거나 줄여 저장하는.', 0),
  (447, '파일과 편집 · 화면을 이미지로', '생활', 1, '다음 작업의 이름은? 화면에 표시된 내용을 이미지로 기록하는', '["스캔","자르기","실행 취소","화면 캡처"]', '["화면 캡처"]', '화면 캡처 — 화면에 표시된 내용을 이미지로 기록하는.', 0),
  (448, '파일과 편집 · 종이 문서 읽기', '생활', 4, '다음 작업의 이름은? 종이 문서를 스캐너로 읽어 디지털 이미지로 만드는', '[]', '["스캔"]', '스캔 — 종이 문서를 스캐너로 읽어 디지털 이미지로 만드는.', 0),
  (449, '파일과 편집 · 영상 양끝 다듬기', '생활', 2, '다음 작업의 이름은? 동영상의 시작이나 끝에서 불필요한 시간을 제거하는', '["자르기","실행 취소","트리밍","압축"]', '["트리밍"]', '트리밍 — 동영상의 시작이나 끝에서 불필요한 시간을 제거하는.', 0),
  (450, '파일과 편집 · 사진 가장자리 정리', '생활', 5, '다음 작업의 이름은? 사진의 가장자리를 잘라 원하는 부분만 남기는', '[]', '["자르기","크롭","크로핑"]', '자르기 — 사진의 가장자리를 잘라 원하는 부분만 남기는.', 0),
  (451, '파일과 편집 · 다시 붙일 내용', '생활', 6, '다음 작업의 이름은? 문서에서 같은 내용을 다른 위치에 그대로 복제할 때 먼저 실행하는', '["실행 취소","복사","압축","스캔"]', '["복사"]', '복사 — 문서에서 같은 내용을 다른 위치에 그대로 복제할 때 먼저 실행하는.', 60),
  (452, '파일과 편집 · 직전 편집 되돌리기', '생활', 3, '다음 작업의 이름은? 바로 전에 실행한 편집 작업을 취소하는', '[]', '["실행 취소","실행취소"]', '실행 취소 — 바로 전에 실행한 편집 작업을 취소하는.', 0),
  (453, '계량 단위 · 1킬로그램을 그램으로 환산한 수', '생활', 0, '다음 값을 숫자로 쓰면 얼마일까요? 1킬로그램을 그램으로 환산한 수', '[]', '["1000","1000g","1000그램"]', '1 kg은 1,000 g이에요.', 0),
