-- 기본 몬스터 번호는 기존 g1~g500 공유 링크의 숫자 부분
CREATE TABLE geez_questions (
  number INTEGER PRIMARY KEY CHECK (number > 0),
  name TEXT NOT NULL,
  tag TEXT NOT NULL,
  art INTEGER NOT NULL CHECK (art BETWEEN 0 AND 8),
  question TEXT NOT NULL,
  choices TEXT NOT NULL CHECK (json_valid(choices)),
  answers TEXT NOT NULL CHECK (json_valid(answers)),
  explanation TEXT NOT NULL,
  seconds INTEGER NOT NULL
);

-- 던전은 원본 문항을 참조하고 선택 순서만 별도로 저장
CREATE TABLE geez_dungeons (
  number INTEGER PRIMARY KEY CHECK (number > 0),
  name TEXT NOT NULL,
  tag TEXT NOT NULL
);
CREATE TABLE geez_dungeon_items (
  dungeon INTEGER NOT NULL REFERENCES geez_dungeons(number),
  position INTEGER NOT NULL CHECK (position >= 0),
  question INTEGER NOT NULL REFERENCES geez_questions(number),
  PRIMARY KEY (dungeon, position),
  UNIQUE (dungeon, question)
);

-- 시연 표본은 회원 계정과 분리해 실제 회원 기록에 미치는 영향 방지
CREATE TABLE geez_demo_attempts (
  profile TEXT NOT NULL,
  question INTEGER NOT NULL REFERENCES geez_questions(number),
  correct INTEGER NOT NULL CHECK (correct IN (0, 1)),
  PRIMARY KEY (profile, question)
);






























